import React, { useState } from "react";
import { Bell, Check, Trash2, UserPlus, Shield, MessageSquare, Trello, Clock } from "lucide-react";

// Mock list of initial notifications
const INITIAL_NOTIFICATIONS = [
  {
    id: "1",
    type: "role_change",
    title: "Role Promoted",
    message: "Kabil promoted you to Admin in Zaalima Workspace",
    time: new Date(Date.now() - 1000 * 60 * 15), // 15 mins ago
    read: false,
    actor: { name: "Kabil", avatarColor: "#6366f1" },
    workspace: "Zaalima",
  },
  {
    id: "2",
    type: "board_invite",
    title: "Added to Board",
    message: "Sajid added you to board 'Design Sprint'",
    time: new Date(Date.now() - 1000 * 60 * 120), // 2 hours ago
    read: false,
    actor: { name: "Sajid", avatarColor: "#ec4899" },
    workspace: "Zaalima",
    board: "Design Sprint",
  },
  {
    id: "3",
    type: "mention",
    title: "Mentioned you in a comment",
    message: "@Kabil: 'Looks good to me, let's deploy the changes.'",
    time: new Date(Date.now() - 1000 * 60 * 360), // 6 hours ago
    read: false,
    actor: { name: "Kabil", avatarColor: "#6366f1" },
    workspace: "Zaalima",
    card: "Database Schema Review",
  },
  {
    id: "4",
    type: "due_date",
    title: "Card Due Soon",
    message: "The card 'Implement drag-and-drop' in Design Sprint is due in 2 hours",
    time: new Date(Date.now() - 1000 * 60 * 720), // 12 hours ago
    read: true,
    actor: { name: "System", avatarColor: "#7c3aed" },
    workspace: "Zaalima",
    card: "Implement drag-and-drop",
  },
  {
    id: "5",
    type: "general",
    title: "Workspace Update",
    message: "Zaalima workspace settings updated by owner Kabil",
    time: new Date(Date.now() - 1000 * 60 * 1440), // 1 day ago
    read: true,
    actor: { name: "Kabil", avatarColor: "#6366f1" },
    workspace: "Zaalima",
  },
];

const NotificationsPage = () => {
  const [notifications, setNotifications] = useState(INITIAL_NOTIFICATIONS);
  const [activeTab, setActiveTab] = useState("all"); // 'all', 'unread', 'mentions'

  const handleMarkAsRead = (id) => {
    setNotifications((prev) =>
      prev.map((n) => (n.id === id ? { ...n, read: true } : n))
    );
  };

  const handleToggleRead = (id) => {
    setNotifications((prev) =>
      prev.map((n) => (n.id === id ? { ...n, read: !n.read } : n))
    );
  };

  const handleDelete = (id) => {
    setNotifications((prev) => prev.filter((n) => n.id !== id));
  };

  const handleMarkAllRead = () => {
    setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
  };

  const filteredNotifications = notifications.filter((n) => {
    if (activeTab === "unread") return !n.read;
    if (activeTab === "mentions") return n.type === "mention";
    return true;
  });

  const unreadCount = notifications.filter((n) => !n.read).length;
  const mentionsCount = notifications.filter((n) => n.type === "mention").length;

  const getIcon = (type) => {
    switch (type) {
      case "role_change":
        return <Shield size={16} className="text-amber-400" />;
      case "board_invite":
        return <Trello size={16} className="text-blue-400" />;
      case "mention":
        return <MessageSquare size={16} className="text-emerald-400" />;
      case "due_date":
        return <Clock size={16} className="text-rose-400" />;
      default:
        return <Bell size={16} className="text-violet-400" />;
    }
  };

  const formatTime = (date) => {
    const diffMs = Date.now() - date.getTime();
    const diffMins = Math.floor(diffMs / (1000 * 60));
    const diffHours = Math.floor(diffMs / (1000 * 60 * 60));

    if (diffMins < 60) return `${diffMins}m ago`;
    if (diffHours < 24) return `${diffHours}h ago`;
    return date.toLocaleDateString("en-US", { month: "short", day: "numeric" });
  };

  return (
    <div style={{ maxWidth: 680, margin: "0 auto", padding: "36px 24px" }}>
      {/* Header */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", marginBottom: 28 }}>
        <div>
          <h1 style={{ fontSize: 26, fontWeight: 800, color: "var(--text-primary)", marginBottom: 4 }}>
            Notifications
          </h1>
          <p style={{ fontSize: 14, color: "var(--text-secondary)" }}>
            Keep track of activity in your workspaces
          </p>
        </div>
        {unreadCount > 0 && (
          <button
            onClick={handleMarkAllRead}
            style={{
              background: "transparent",
              border: "none",
              color: "var(--brand-500)",
              fontSize: 13,
              fontWeight: 600,
              cursor: "pointer",
              display: "flex",
              alignItems: "center",
              gap: 6,
              padding: "6px 12px",
              borderRadius: "var(--radius-md)",
              transition: "background var(--transition-fast)",
            }}
            onMouseEnter={(e) => (e.currentTarget.style.background = "var(--bg-hover)")}
            onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}
          >
            <Check size={14} />
            Mark all read
          </button>
        )}
      </div>

      {/* Tabs */}
      <div
        style={{
          display: "flex",
          gap: 6,
          borderBottom: "1px solid var(--border-subtle)",
          marginBottom: 20,
          paddingBottom: 2,
        }}
      >
        {[
          { id: "all", label: "All", count: notifications.length },
          { id: "unread", label: "Unread", count: unreadCount },
          { id: "mentions", label: "Mentions", count: mentionsCount },
        ].map((tab) => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            style={{
              position: "relative",
              padding: "10px 16px",
              background: "transparent",
              border: "none",
              color: activeTab === tab.id ? "var(--text-primary)" : "var(--text-secondary)",
              fontWeight: activeTab === tab.id ? 600 : 500,
              fontSize: 14,
              cursor: "pointer",
              transition: "color var(--transition-fast)",
            }}
          >
            <span style={{ display: "flex", alignItems: "center", gap: 6 }}>
              {tab.label}
              {tab.count > 0 && (
                <span
                  style={{
                    fontSize: 11,
                    fontWeight: 700,
                    padding: "1px 6px",
                    borderRadius: 10,
                    background: activeTab === tab.id ? "var(--brand-500)" : "var(--bg-hover)",
                    color: activeTab === tab.id ? "#fff" : "var(--text-secondary)",
                    transition: "all var(--transition-fast)",
                  }}
                >
                  {tab.count}
                </span>
              )}
            </span>
            {activeTab === tab.id && (
              <div
                style={{
                  position: "absolute",
                  bottom: -3,
                  left: 0,
                  right: 0,
                  height: 2,
                  background: "var(--brand-500)",
                  borderRadius: 2,
                }}
              />
            )}
          </button>
        ))}
      </div>

      {/* Notifications list */}
      {filteredNotifications.length === 0 ? (
        <div style={{ textAlign: "center", padding: "64px 0" }}>
          <div
            style={{
              width: 64,
              height: 64,
              borderRadius: "var(--radius-xl)",
              background: "var(--bg-card)",
              border: "1px solid var(--border-subtle)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              margin: "0 auto 16px",
              fontSize: 24,
              color: "var(--text-tertiary)",
            }}
          >
            🔔
          </div>
          <p style={{ fontSize: 15, color: "var(--text-secondary)", fontWeight: 500 }}>
            All caught up!
          </p>
          <p style={{ fontSize: 13, color: "var(--text-tertiary)", marginTop: 4 }}>
            No notifications in this category
          </p>
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          {filteredNotifications.map((notif) => (
            <div
              key={notif.id}
              style={{
                display: "flex",
                gap: 14,
                padding: "16px",
                borderRadius: "var(--radius-lg)",
                background: "var(--bg-card)",
                border: `1.5px solid ${notif.read ? "var(--border-subtle)" : "var(--brand-500)"}`,
                boxShadow: "var(--shadow-sm)",
                transition: "all var(--transition-fast)",
                position: "relative",
              }}
            >
              {/* Actor Avatar */}
              <div
                style={{
                  width: 38,
                  height: 38,
                  borderRadius: "50%",
                  backgroundColor: notif.actor.avatarColor,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  color: "#fff",
                  fontWeight: 700,
                  fontSize: 14,
                  flexShrink: 0,
                }}
              >
                {notif.actor.name[0].toUpperCase()}
              </div>

              {/* Content */}
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      width: 24,
                      height: 24,
                      borderRadius: 6,
                      background: "var(--bg-hover)",
                      flexShrink: 0,
                    }}
                  >
                    {getIcon(notif.type)}
                  </div>
                  <span style={{ fontSize: 13, fontWeight: 700, color: "var(--text-primary)" }}>
                    {notif.title}
                  </span>
                  <span style={{ fontSize: 11, color: "var(--text-tertiary)", marginLeft: "auto" }}>
                    {formatTime(notif.time)}
                  </span>
                </div>
                <p
                  style={{
                    fontSize: 13.5,
                    color: notif.read ? "var(--text-secondary)" : "var(--text-primary)",
                    margin: 0,
                    lineHeight: 1.4,
                  }}
                >
                  {notif.message}
                </p>
              </div>

              {/* Actions */}
              <div style={{ display: "flex", flexDirection: "column", gap: 8, justifyContent: "space-between", flexShrink: 0 }}>
                <button
                  onClick={() => handleToggleRead(notif.id)}
                  title={notif.read ? "Mark as unread" : "Mark as read"}
                  style={{
                    background: "transparent",
                    border: "none",
                    cursor: "pointer",
                    color: notif.read ? "var(--text-tertiary)" : "var(--brand-500)",
                    padding: 4,
                    display: "flex",
                    borderRadius: "var(--radius-sm)",
                    transition: "color var(--transition-fast)",
                  }}
                  onMouseEnter={(e) => (e.currentTarget.style.background = "var(--bg-hover)")}
                  onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}
                >
                  <Check size={14} style={{ opacity: notif.read ? 0.4 : 1 }} />
                </button>
                <button
                  onClick={() => handleDelete(notif.id)}
                  title="Delete notification"
                  style={{
                    background: "transparent",
                    border: "none",
                    cursor: "pointer",
                    color: "var(--text-tertiary)",
                    padding: 4,
                    display: "flex",
                    borderRadius: "var(--radius-sm)",
                    transition: "color var(--transition-fast)",
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.background = "var(--bg-hover)";
                    e.currentTarget.style.color = "var(--accent-rose)";
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.background = "transparent";
                    e.currentTarget.style.color = "var(--text-tertiary)";
                  }}
                >
                  <Trash2 size={13} />
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default NotificationsPage;
